// The code indicates why the run was terminated. Additional codes might be
// introduced in future releases. * `SUCCESS`: The run was completed
// successfully. * `SUCCESS_WITH_FAILURES`: The run was completed successfully
// but some child runs failed. * `USER_CANCELED`: The run was successfully
// canceled during execution by a user. * `CANCELED`: The run was canceled
// during execution by the <Databricks> platform; for example, if the maximum
// run duration was exceeded. * `SKIPPED`: Run was never executed, for example,
// if the upstream task run failed, the dependency type condition was not met,
// or there were no material tasks to execute. * `INTERNAL_ERROR`: The run
// encountered an unexpected error. Refer to the state message for further
// details. * `DRIVER_ERROR`: The run encountered an error while communicating
// with the Spark Driver. * `CLUSTER_ERROR`: The run failed due to a cluster
// error. Refer to the state message for further details. *
// `REPOSITORY_CHECKOUT_FAILED`: Failed to complete the checkout due to an error
// when communicating with the third party service. * `INVALID_CLUSTER_REQUEST`:
// The run failed because it issued an invalid request to start the cluster. *
// `WORKSPACE_RUN_LIMIT_EXCEEDED`: The workspace has reached the quota for the
// maximum number of concurrent active runs. Consider scheduling the runs over a
// larger time frame. * `FEATURE_DISABLED`: The run failed because it tried to
// access a feature unavailable for the workspace. *
// `CLUSTER_REQUEST_LIMIT_EXCEEDED`: The number of cluster creation, start, and
// upsize requests have exceeded the allotted rate limit. Consider spreading the
// run execution over a larger time frame. * `STORAGE_ACCESS_ERROR`: The run
// failed due to an error when accessing the customer blob storage. Refer to the
// state message for further details. * `RUN_EXECUTION_ERROR`: The run was
// completed with task failures. For more details, refer to the state message or
// run output. * `UNAUTHORIZED_ERROR`: The run failed due to a permission issue
// while accessing a resource. Refer to the state message for further details. *
// `LIBRARY_INSTALLATION_ERROR`: The run failed while installing the
// user-requested library. Refer to the state message for further details. The
// causes might include, but are not limited to: The provided library is
// invalid, there are insufficient permissions to install the library, and so
// forth. * `MAX_CONCURRENT_RUNS_EXCEEDED`: The scheduled run exceeds the limit
// of maximum concurrent runs set for the job. * `MAX_SPARK_CONTEXTS_EXCEEDED`:
// The run is scheduled on a cluster that has already reached the maximum number
// of contexts it is configured to create. See: [Link]. * `RESOURCE_NOT_FOUND`:
// A resource necessary for run execution does not exist. Refer to the state
// message for further details. * `INVALID_RUN_CONFIGURATION`: The run failed
// due to an invalid configuration. Refer to the state message for further
// details. * `CLOUD_FAILURE`: The run failed due to a cloud provider issue.
// Refer to the state message for further details. *
// `MAX_JOB_QUEUE_SIZE_EXCEEDED`: The run was skipped due to reaching the job
// level queue size limit. * `DISABLED`: The run was never executed because it
// was disabled explicitly by the user. * `BREAKING_CHANGE`: Run failed because
// of an intentional breaking change in Spark, but it will be retried with a
// mitigation config. * `CLUSTER_TERMINATED_BY_USER`: The run failed because the
// externally managed cluster entered an unusable state, likely due to the user
// terminating or restarting it outside the jobs service.
//
// [Link]: https://kb.databricks.com/en_US/notebooks/too-many-execution-contexts-are-open-right-now
type TerminationCode_Code string

const (
	TerminationCode_Code_Unspecified TerminationCode_Code = ""
	TerminationCode_Code_Success     TerminationCode_Code = "SUCCESS"
	TerminationCode_Code_Canceled    TerminationCode_Code = "CANCELED"
	// DriverError represents failures when the driver restarted, or became
	// unhealthy or unreachable during the run.
	TerminationCode_Code_DriverError TerminationCode_Code = "DRIVER_ERROR"
	// ClusterError represents failures due to cluster issues. These include the
	// failures that occur during creation of a new cluster / starting up an
	// existing cluster, cluster issues and timeouts during the job run
	TerminationCode_Code_ClusterError TerminationCode_Code = "CLUSTER_ERROR"
	// Returned if [[ProjectCheckoutInternalRepo]] RPC fails
	TerminationCode_Code_RepositoryCheckoutFailed TerminationCode_Code = "REPOSITORY_CHECKOUT_FAILED"
	// * InvalidClusterRequest represents failures when the user provides invalid
	// input for a cluster configuration for the run. For example, providing invalid
	// parameter Values in the request/ providing a bad request etc
	TerminationCode_Code_InvalidClusterRequest TerminationCode_Code = "INVALID_CLUSTER_REQUEST"
	// * Returned if an org set a limit for number of their concurrent active runs
	// and the run couldn't start because it would exceed this limit. TODO:
	// JOBS-12528: The original comment (on the issue) does not seem to reflect how
	// this is actually used in code It should be looked into how we're handling the
	// scenario where a given job exceeds its own internal concurrency limits.
	TerminationCode_Code_WorkspaceRunLimitExceeded TerminationCode_Code = "WORKSPACE_RUN_LIMIT_EXCEEDED"
	TerminationCode_Code_FeatureDisabled           TerminationCode_Code = "FEATURE_DISABLED"
	// * ClusterRequestLimitExceeded represents failures when cluster creation,
	// start, and upsize requests for a workspace exceeded the rate limit of
	// [[com.databricks.backend.cluster.ClusterSizeConf.upsizeRefillRatePerMinPerOrg]]
	// nodes per min.
	TerminationCode_Code_ClusterRequestLimitExceeded TerminationCode_Code = "CLUSTER_REQUEST_LIMIT_EXCEEDED"
	// * StorageAccessError represents failures when the access to user's
	// <Databricks> file system fails. For example, misconfiguration on user's side
	// like deleting AWS S3 bucket without cancelling the workspace, their Azure
	// account being disabled, the storage buckets not being found etc.
	TerminationCode_Code_StorageAccessError TerminationCode_Code = "STORAGE_ACCESS_ERROR"
	TerminationCode_Code_RunExecutionError  TerminationCode_Code = "RUN_EXECUTION_ERROR"
	TerminationCode_Code_UnauthorizedError  TerminationCode_Code = "UNAUTHORIZED_ERROR"
	// * LibraryInstallationError represents failures due to issues related library
	// installation. These include the failures that occur when the user provided
	// invalid library or user not having enough permissions to install the library
	// or any cloud dependency/ infrastructure failures during library installation
	// etc
	TerminationCode_Code_LibraryInstallationError  TerminationCode_Code = "LIBRARY_INSTALLATION_ERROR"
	TerminationCode_Code_MaxConcurrentRunsExceeded TerminationCode_Code = "MAX_CONCURRENT_RUNS_EXCEEDED"
	TerminationCode_Code_MaxSparkContextsExceeded  TerminationCode_Code = "MAX_SPARK_CONTEXTS_EXCEEDED"
	TerminationCode_Code_ResourceNotFound          TerminationCode_Code = "RESOURCE_NOT_FOUND"
	TerminationCode_Code_InvalidRunConfiguration   TerminationCode_Code = "INVALID_RUN_CONFIGURATION"
	TerminationCode_Code_InternalError             TerminationCode_Code = "INTERNAL_ERROR"
	TerminationCode_Code_CloudFailure              TerminationCode_Code = "CLOUD_FAILURE"
	TerminationCode_Code_MaxJobQueueSizeExceeded   TerminationCode_Code = "MAX_JOB_QUEUE_SIZE_EXCEEDED"
	TerminationCode_Code_Skipped                   TerminationCode_Code = "SKIPPED"
	TerminationCode_Code_UserCanceled              TerminationCode_Code = "USER_CANCELED"
	TerminationCode_Code_BudgetPolicyLimitExceeded TerminationCode_Code = "BUDGET_POLICY_LIMIT_EXCEEDED"
	TerminationCode_Code_Disabled                  TerminationCode_Code = "DISABLED"
	// SuccessWithFailures represents that some child runs failed but the run was
	// ultimately successful.
	TerminationCode_Code_SuccessWithFailures TerminationCode_Code = "SUCCESS_WITH_FAILURES"
	// Run failed because of an intentional breaking change in Spark, but it will be
	// retried with a mitigation config.
	TerminationCode_Code_BreakingChange TerminationCode_Code = "BREAKING_CHANGE"
)

// * `SUCCESS`: The run terminated without any issues * `INTERNAL_ERROR`: An
